p='src-tauri/src/updates/native.rs';s=open(p).read();at=s.index('#[cfg(test)]');head='''use std::{path::Path, sync::OnceLock, time::Duration};

use serde::Serialize;
use tauri::ipc::Channel;
use tauri_plugin_updater::{Update, UpdaterExt};

use super::{CancelRegistration, DOWNLOAD_CANCEL, DOWNLOAD_LOCK, DownloadProgress, DownloadedUpdate, Release, ReleaseAsset, UpdateChannel, client, current_identity, download_and_verify, release_or_cancel, requested_release_from, selected_asset, API_RELEASES};

struct StagedUpdate {
    update: Update,
    channel: UpdateChannel,
    directory: tempfile::TempDir,
    installed: bool,
}

static STAGED: OnceLock<tokio::sync::Mutex<Option<StagedUpdate>>> = OnceLock::new();

#[derive(Clone, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum InstallProgress { Installing, Restarting }

pub(super) fn payload_name(tag: &str, os: &str, arch: &str) -> Option<String> {
    let package = super::package_name(tag, os, arch)?;
    let platform = package.strip_prefix("mesh-talk_")?.strip_suffix(".zip")?;
    let extension = match os { "macos" => "app.tar.gz", "windows" => "nsis.exe", "linux" => "AppImage", _ => return None };
    Some(format!("mesh-talk-update_{platform}.{extension}"))
}

fn supported_install(os: &str, executable: &Path, has_key: bool, development: bool, appimage: bool) -> bool {
    if !has_key || development { return false; }
    match os {
        "macos" => !executable.starts_with("/Volumes") && executable.parent().is_some_and(|macos| {
            macos.file_name().is_some_and(|name| name == "MacOS") && macos.parent().is_some_and(|contents| {
                contents.file_name().is_some_and(|name| name == "Contents") && contents.parent().is_some_and(|bundle| bundle.extension().is_some_and(|extension| extension == "app"))
            })
        }),
        "windows" => executable.extension().is_some_and(|extension| extension.eq_ignore_ascii_case("exe")),
        "linux" => appimage,
        _ => false,
    }
}

fn public_key() -> &'static str { option_env!("MESH_TALK_UPDATER_PUBLIC_KEY").unwrap_or("").trim() }

pub(super) fn available() -> bool {
    std::env::current_exe().is_ok_and(|executable| supported_install(std::env::consts::OS, &executable, !public_key().is_empty(), cfg!(debug_assertions), std::env::var_os("APPIMAGE").is_some()))
}

pub(super) fn assets<'a>(release: &'a Release, os: &str, arch: &str) -> Option<(&'a ReleaseAsset, &'a ReleaseAsset)> {
    let name = payload_name(&release.tag_name, os, arch)?;
    let payload = selected_asset(release, &name)?;
    let signature = selected_asset(release, &format!("{name}.sig"))?;
    (signature.size <= 16 * 1024).then_some((payload, signature))
}

async fn signature_from(http: &reqwest::Client, asset: &ReleaseAsset) -> Result<String, String> {
    use sha2::{Digest, Sha256};
    if asset.size > 16 * 1024 { return Err("The update signature is too large".into()); }
    let mut response = http.get(&asset.browser_download_url).send().await.map_err(|_| "Could not download the update signature")?.error_for_status().map_err(|_| "Could not download the update signature")?;
    let mut bytes = Vec::new();
    while let Some(chunk) = response.chunk().await.map_err(|_| "Could not read the update signature")? {
        if bytes.len() as u64 + chunk.len() as u64 > asset.size { return Err("The update signature has an unexpected size".into()); }
        bytes.extend_from_slice(&chunk);
    }
    if bytes.len() as u64 != asset.size || asset.digest.as_deref() != Some(format!("sha256:{}", hex::encode(Sha256::digest(&bytes))).as_str()) {
        return Err("The update signature failed its integrity check".into());
    }
    String::from_utf8(bytes).map_err(|_| "The update signature is invalid".into())
}

#[tauri::command]
pub async fn prepare_update(app: tauri::AppHandle, version: String, update_channel: Option<UpdateChannel>, on_progress: Channel<DownloadProgress>) -> Result<DownloadedUpdate, String> {
    if !available() { return Err("Use the manual installer for this installation".into()); }
    let _guard = DOWNLOAD_LOCK.get_or_init(|| tokio::sync::Mutex::new(())).try_lock().map_err(|_| "An update is already in progress")?;
    let (sender, cancel) = tokio::sync::watch::channel(false);
    *DOWNLOAD_CANCEL.get_or_init(|| std::sync::Mutex::new(None)).lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(sender);
    let _registration = CancelRegistration;
    let channel = update_channel.unwrap_or_default();
    *STAGED.get_or_init(|| tokio::sync::Mutex::new(None)).lock().await = None;
    let release = requested_release_from(&client(Duration::from_secs(20))?, API_RELEASES, &version, channel, &current_identity(), cancel.clone()).await?;
    let (payload, signature) = assets(&release, std::env::consts::OS, std::env::consts::ARCH).ok_or("This release needs a manual installation")?;
    let signature = release_or_cancel(signature_from(&client(Duration::from_secs(30))?, signature), cancel.clone()).await?;
    let current = current_identity();
    let update = app.updater_builder().pubkey(public_key()).endpoints(vec![API_RELEASES.parse().expect("fixed HTTPS endpoint")]).map_err(|_| "Could not prepare the updater")?
        .version_comparator(move |_, remote| super::ReleaseIdentity::parse(&format!("v{}", remote.version)).is_ok_and(|candidate| candidate > current))
        .build().map_err(|_| "Could not prepare the native installer")?
        .restore_update(serde_json::json!({ "version": version, "url": payload.browser_download_url, "signature": signature.trim() }))
        .map_err(|_| "The update metadata is invalid")?.ok_or("This release is no longer an update")?;
    let directory = tempfile::tempdir().map_err(|_| "Could not prepare the update folder")?;
    let path = directory.path().join("payload");
    let mut file = tokio::fs::File::create(&path).await.map_err(|_| "Could not create the update file")?;
    download_and_verify(payload, &mut file, &on_progress, cancel.clone()).await?;
    drop(file);
    let bytes = tokio::fs::read(&path).await.map_err(|_| "Could not read the downloaded update")?;
    let verifier = update.clone();
    tokio::task::spawn_blocking(move || verifier.verify(&bytes)).await.map_err(|_| "Update verification was interrupted")?.map_err(|_| "The update signature or signed version is invalid. Use the release page to download manually")?;
    if *cancel.borrow() { return Err("Download canceled".into()); }
    let result = DownloadedUpdate { path: path.to_string_lossy().into_owned(), file_name: payload.name.clone(), installable: true };
    *STAGED.get().expect("initialized stage").lock().await = Some(StagedUpdate { update, channel, directory, installed: false });
    Ok(result)
}

#[tauri::command]
pub async fn install_update(app: tauri::AppHandle, version: String, update_channel: Option<UpdateChannel>, on_progress: Channel<InstallProgress>) -> Result<(), String> {
    let _guard = DOWNLOAD_LOCK.get_or_init(|| tokio::sync::Mutex::new(())).try_lock().map_err(|_| "An update is already in progress")?;
    let mut staged = STAGED.get_or_init(|| tokio::sync::Mutex::new(None)).lock().await;
    let staged = staged.as_mut().filter(|staged| staged.update.version == version && staged.channel == update_channel.unwrap_or_default()).ok_or("Download and verify this update before installing")?;
    if !staged.installed {
        let _ = on_progress.send(InstallProgress::Installing);
        let bytes = tokio::fs::read(staged.directory.path().join("payload")).await.map_err(|_| "The prepared update is unavailable. Download it again")?;
        let update = staged.update.clone();
        tokio::task::spawn_blocking(move || update.install(bytes)).await.map_err(|_| "Update installation was interrupted")?.map_err(|error| {
            log::warn!("native update installation failed: {error}");
            "Could not install the update. Authorization may have been canceled or the installation folder may be read-only. Retry or use the manual installer".to_string()
        })?;
        staged.installed = true;
    }
    let _ = on_progress.send(InstallProgress::Restarting);
    // Tauri relaunches macOS bundles through LaunchServices and emits Exit so
    // single-instance resources and window state are released before reopening.
    app.request_restart();
    Ok(())
}

