use base64::{Engine, engine::general_purpose::STANDARD};
fn main() {
    let args: Vec<_> = std::env::args().collect();
    let decode = |path: &str| -> String {
        let encoded = std::fs::read_to_string(path).expect("read public verification input");
        String::from_utf8(STANDARD.decode(encoded.trim()).expect("decode verification input")).expect("text verification input")
    };
    let key = minisign_verify::PublicKey::decode(&decode(&args[1])).expect("valid public key");
    let signature_text = decode(&args[2]);
    assert!(signature_text.lines().any(|line| line.starts_with("trusted comment: ") && line.ends_with("\tversion:0.0.0-setup.1")));
    let signature = minisign_verify::Signature::decode(&signature_text).expect("valid signature");
    let payload = std::fs::read(&args[3]).expect("read test payload");
    key.verify(&payload, &signature, false).expect("matching key pair verifies signed bytes and trusted version comment");
    assert!(key.verify(b"tampered", &signature, false).is_err());
    println!("Signing key pair verified cryptographically; tampered payload rejected");
}
