use super::{ReleaseAsset, ReleaseIdentity, native::payload_name};

pub(super) const MAX_CATALOG_SIZE: u64 = 64 * 1024;
const MAX_BASE_SIZE: u64 = 128 * 1024 * 1024;
const MAX_TARGET_SIZE: u64 = 256 * 1024 * 1024;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Artifact {
    pub name: String,
    pub size: u64,
    pub sha256: String,
}

impl Artifact {
    fn valid(&self) -> bool {
        self.size > 0 && self.sha256.len() == 64
            && self.sha256.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
    }

    pub fn matches(&self, asset: &ReleaseAsset) -> bool {
        self.name == asset.name && self.size == asset.size
            && asset.digest.as_deref() == Some(format!("sha256:{}", self.sha256).as_str())
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Base {
    pub tag: String,
    pub size: u64,
    pub sha256: String,
    pub patch: Artifact,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(super) struct Catalog {
    schema: u32,
    role: String,
    pub algorithm: String,
    tag: String,
    release_kind: String,
    os: String,
    arch: String,
    pub fallback: Artifact,
    pub target: Artifact,
    pub bases: Vec<Base>,
}

pub(super) fn catalog_name(tag: &str, os: &str, arch: &str) -> Option<String> {
    let full = payload_name(tag, os, arch)?;
    Some(format!("{}.delta.json", full.strip_prefix("mesh-talk-update_")
        .map(|suffix| format!("mesh-talk-update_{suffix}"))?))
}

pub(super) fn worthwhile(full: u64, patch: u64, overhead: u64) -> bool {
    let total = u128::from(patch) + u128::from(overhead);
    total + 1024 * 1024 <= u128::from(full) && total * 4 <= u128::from(full) * 3
}

impl Catalog {
    /// Never call this with unauthenticated catalog bytes.
    pub fn parse(bytes: &[u8], tag: &str, os: &str, arch: &str) -> Result<Self, String> {
        let invalid = || "The signed delta catalog contradicts this release".to_owned();
        if bytes.len() as u64 > MAX_CATALOG_SIZE || !matches!(os, "macos" | "windows") {
            return Err(invalid());
        }
        let catalog: Self = serde_json::from_slice(bytes).map_err(|_| invalid())?;
        let identity = ReleaseIdentity::parse(tag)?;
        let full = payload_name(tag, os, arch).ok_or_else(invalid)?;
        let raw = full.replacen("mesh-talk-update_", "mesh-talk-update-raw_", 1);
        if catalog.schema != 1 || catalog.role != "mesh-talk-delta" || catalog.tag != tag
            || catalog.os != os || catalog.arch != arch
            || catalog.release_kind != if identity.is_nightly() { "nightly" } else { "stable" }
            || catalog.fallback.name != full || catalog.target.name != raw
            || !catalog.fallback.valid() || !catalog.target.valid()
            || catalog.target.size > MAX_TARGET_SIZE || catalog.bases.is_empty() || catalog.bases.len() > 2
        { return Err(invalid()); }
        let platform = super::package_name(tag, os, arch).ok_or_else(invalid)?;
        let stem = platform.strip_prefix("mesh-talk_").and_then(|s| s.strip_suffix(".zip")).ok_or_else(invalid)?;
        let mut seen = std::collections::HashSet::new();
        for base in &catalog.bases {
            let base_identity = ReleaseIdentity::parse(&base.tag)?;
            let base_artifact = Artifact { name: String::new(), size: base.size, sha256: base.sha256.clone() };
            if base_identity >= identity || base_identity.is_nightly() != identity.is_nightly()
                || base.tag.ends_with("-dev") || !seen.insert(&base.tag)
                || base.size > MAX_BASE_SIZE || !base_artifact.valid() || !base.patch.valid()
                || base.patch.name != format!("mesh-talk-patch_{stem}_from-{}.zst", base.tag)
            { return Err(invalid()); }
        }
        Ok(catalog)
    }

    pub fn matching_base(&self, tag: &str, size: u64, sha256: &str) -> Option<&Base> {
        self.bases.iter().find(|base| base.tag == tag && base.size == size && base.sha256 == sha256)
    }
}

